fn main(){let r=Path::new(R);for file in["flow.rs","flow-body.rs"]{let p=r.join(file);let mut s=fs::read_to_string(&p).unwrap();assert_eq!(s.matches("\"bootstrap-flow.rs\"").count(),1);s=s.replace("\"bootstrap-flow.rs\"","\"make-flow.rs\",\"prepare-aux.rs\",\"extra.rs\",\"extra\",\"extra-tests\",\"extra-tests.log\"");fs::write(&p,s).unwrap();}let p=r.join("design.md");let mut s=fs::read_to_string(&p).unwrap();s.push_str("\nBefore any candidate execution, the initial compile failed E0277: the map_init initializer captured &Scope, whose Rc marker deliberately forbids Sync. Retain initial-attempt source/pins/logs/binaries; copy the numeric parent ID before the closure. No unsafe trait implementation or successful run is repeated. Actual flow generation uses make-flow.rs followed by prepare-aux.rs; the inherited bootstrap-flow.rs is unused. Extra decoder/interval/ownership analysis is compiled and three tests pass before capture.\n");fs::write(p,s).unwrap();println!("Auxiliary analysis pinned before capture; failed compile preserved");}
